+        confirm(&first, "http://a", &prompt, 2);
+        // c stakes 3 blocks (deeper than a's 2), d stakes 2 (equal) and e 1.
+        for (url, blocks) in [("http://c", 3), ("http://d", 2), ("http://e", 1)] {
